INSERT INTO `blog_categories` VALUES (1,'Manufacturing Insights','manufacturing-insights','Behind-the-scenes engineering of streetwear fabrics, loopback fleece, and dye methods.',1,1,'2026-10-03 01:58:03','2026-10-03 01:58:03'),(2,'Customizer & 3D Design','customizer-guides','How-to guides on leveraging 3D mockups and precision embroidery placement.',2,1,'2026-10-03 01:58:03','2026-10-03 01:58:03'),(3,'Fabric Sourcing & GSM','fabric-sourcing-gsm','Comprehensive breakdowns on textile weights, French Terry loopback structures, single jerseys, and yarn spinning.',1,1,'2026-10-12 18:30:29','2026-10-12 18:30:29'),(4,'Technical Manufacturing','technical-manufacturing','Factory floor techniques, ultrasonic bonding, AQL 2.5 quality control standards, and precision needlework.',2,1,'2026-10-12 18:30:29','2026-10-12 18:30:29'),(5,'Private Label Strategy','private-label-strategy','How high-growth D2C brands navigate tech packs, damask neck tags, custom hardware, and retail packaging.',3,1,'2026-10-12 18:30:29','2026-10-12 18:30:29'),(6,'Teamwear & Sports Tech','teamwear-sports-tech','Engineering high-performance garments for cycling peloton clubs, equestrian federations, and pro ice hockey.',4,1,'2026-10-12 18:30:29','2026-10-12 18:30:29'),(7,'Logistics & Incoterms','logistics-incoterms','Global freight optimization, comparing FOB vs DDP, customs documentation, and commercial container transit.',5,1,'2026-10-12 18:30:29','2026-10-12 18:30:29');
