tion\":\"5 pcs\"}],\"pom_grading\":{\"XS\":{\"chest\":46,\"waist\":40,\"back_length\":64,\"sleeve\":61},\"S\":{\"chest\":49,\"waist\":43,\"back_length\":66,\"sleeve\":62},\"M\":{\"chest\":52,\"waist\":46,\"back_length\":68,\"sleeve\":63},\"L\":{\"chest\":55,\"waist\":49,\"back_length\":70,\"sleeve\":64}}}','[\"equestrian\"]',1,4,'2026-10-13 16:35:51','2026-10-13 16:35:51'),(36,'trim','trim_snap_silver','Polished Nickel / Silver Snaps','{\"hex\":\"#E4E4E7\",\"material\":\"Nickel Plated Brass\"}','[\"all\"]',1,1,'2026-10-13 16:35:51','2026-10-13 16:35:51'),(37,'trim','trim_snap_gold','Varsity Heavy Brass 18K Gold','{\"hex\":\"#CA8A04\",\"material\":\"PVD Electroplated Gold\"}','[\"all\"]',1,2,'2026-10-13 16:35:51','2026-10-13 16:35:51'),(38,'trim','trim_snap_matte_noir','Matte Noir Powder-Coated Snaps','{\"hex\":\"#141414\",\"material\":\"Matte Powder-Coated Metal\"}','[\"all\"]',1,3,'2026-10-13 16:35:51','2026-10-13 16:35:51'),(39,'trim','trim_lining_satin_black','Silk-Satin Thermal Noir Lining','{\"hex\":\"#0A0A0A\",\"material\":\"Cupro Silk Satin\"}','[\"all\"]',1,4,'2026-10-13 16:35:51','2026-10-13 16:35:51'),(40,'trim','trim_lining_quilted_diamond','Insulated Diamond-Quilted Bemberg','{\"hex\":\"#1C1C1E\",\"material\":\"120 GSM Thermal Polyfill + Bemberg\"}','[\"all\"]',1,5,'2026-10-13 16:35:51','2026-10-13 16:35:51');
