DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `wc_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Original WooCommerce Product ID',
  `sku` varchar(100) DEFAULT NULL COMMENT 'Nullable for variable parent products',
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `product_type` varchar(50) NOT NULL DEFAULT 'simple',
  `status` varchar(50) NOT NULL DEFAULT 'published',
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `visibility` varchar(50) NOT NULL DEFAULT 'visible',
  `short_description` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `regular_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `sale_price` decimal(10,2) DEFAULT NULL,
  `wholesale_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `moq` int(10) unsigned NOT NULL DEFAULT 50,
  `default_gsm` int(10) unsigned DEFAULT NULL,
  `fit` varchar(100) DEFAULT NULL,
  `lead_time_days` int(11) NOT NULL DEFAULT 25,
  `sample_available` tinyint(1) NOT NULL DEFAULT 1,
  `sample_price` decimal(10,2) NOT NULL DEFAULT 75.00,
  `is_customizable` tinyint(1) NOT NULL DEFAULT 1,
  `three_d_model_path` varchar(255) DEFAULT NULL,
  `garment_parts_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Canvas zones, masks & layer mappings' CHECK (json_valid(`garment_parts_config`)),
  `manage_stock` tinyint(1) NOT NULL DEFAULT 0,
  `stock_quantity` int(11) NOT NULL DEFAULT 0,
  `stock_status` varchar(50) NOT NULL DEFAULT 'instock',
  `weight_kg` decimal(8,3) DEFAULT NULL,
  `length_cm` decimal(8,2) DEFAULT NULL,
  `width_cm` decimal(8,2) DEFAULT NULL,
  `height_cm` decimal(8,2) DEFAULT NULL,
  `meta_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `canonical_url` varchar(255) DEFAULT NULL,
  `og_image_path` varchar(255) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  KEY `products_wc_id_index` (`wc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

